import json, urllib.request, ssl, time

upstream = json.loads('''$query_tier1_events.message''')
events = upstream.get("events", [])

if not events:
    print(json.dumps({"new_events": [], "skipped_count": 0, "has_new": "false"}))
else:
    batch_community_ids = [e["community_id"] for e in events if e.get("community_id")]

    if not batch_community_ids:
        has_new = "true" if events else "false"
        print(json.dumps({"new_events": events, "skipped_count": 0, "has_new": has_new}))
    else:
        ctx = ssl._create_unverified_context()
        headers = {
            "Content-Type": "application/json",
            "Authorization": "Bearer $thehive_api_key"
        }
        six_hours_ago_ms = int((time.time() - 21600) * 1000)
        search_body = {
            "query": {
                "_and": [
                    {"_gte": {"_field": "createdAt", "_value": six_hours_ago_ms}},
                    {"_in": {
                        "_field": "customFields.community_id.string",
                        "_values": batch_community_ids
                    }}
                ]
            }
        }
        existing_cids = set()
        try:
            req = urllib.request.Request(
                "$thehive_url/api/case/_search?range=0-100",
                data=json.dumps(search_body).encode(),
                headers=headers,
                method="POST"
            )
            resp = urllib.request.urlopen(req, context=ctx, timeout=10)
            cases = json.loads(resp.read().decode())
            if isinstance(cases, dict):
                cases = cases.get("data", [])
            if not isinstance(cases, list):
                cases = []
            for c in cases:
                cf = c.get("customFields", {})
                cid = None
                if isinstance(cf, dict):
                    cid_field = cf.get("community_id", {})
                    if isinstance(cid_field, dict):
                        cid = cid_field.get("string") or cid_field.get("value")
                if cid:
                    existing_cids.add(cid)
        except Exception as e:
            has_new = "true" if events else "false"
            print(json.dumps({"new_events": events, "skipped_count": 0, "has_new": has_new, "dedupe_error": str(e)[:200]}))
        else:
            new_events = [e for e in events if e.get("community_id") not in existing_cids]
            skipped = len(events) - len(new_events)
            has_new = "true" if new_events else "false"
            print(json.dumps({"new_events": new_events, "skipped_count": skipped, "has_new": has_new}))
